q = int(input())
for _ in range(q):
    s = input().strip()
    t = input().strip()
    p = input().strip()

    # Check if s is a subsequence of t
    # We need to verify that we can form t from s by inserting characters from p

    # First, check if s is a subsequence of t
    i = 0  # pointer for s
    for char in t:
        if i < len(s) and s[i] == char:
            i += 1

    # If we've matched all of s with t, then s is a subsequence of t
    if i == len(s):
        # Now check if the remaining characters in t (after matching s) can be formed by characters in p
        remaining_t = t[i:]  # characters in t that are not in s (in order)

        # Count frequency of each character in p
        p_count = {}
        for char in p:
            p_count[char] = p_count.get(char, 0) + 1

        # Count frequency of each character in remaining_t
        remaining_count = {}
        for char in remaining_t:
            remaining_count[char] = remaining_count.get(char, 0) + 1

        # Check if p has enough characters to cover the missing parts in t
        possible = True
        for char in remaining_count:
            if p_count.get(char, 0) < remaining_count[char]:
                possible = False
                break

        if possible:
            print("YES")
        else:
            print("NO")
    else:
        print("NO")
